""" Return the y value of function x """
def get_fx(x: Any, linear: Any) -> object {
    (a, b, offset) = linear;
    y = ((a * x) + b) // offset;
    return y;
}

"""
    Maximize how much each dollar reduces percent diff from level salary. Higher scores get raise dollars first
    :param current_salary:
    :param level_salary:
    :return:
    """
def _calculate_score_for_underpaid(current_salary: Any, level_salary: Any) -> object {
    assert (current_salary <= level_salary);
    absolute_diff = current_salary - level_salary;
    percent_diff = current_salary / level_salary;
    if (absolute_diff != 0) {
        marginal_percentage = percent_diff / absolute_diff;
    } else {
        marginal_percentage = -1.0;
    }
    return marginal_percentage;
}

"""
  Fullwave3D's approximation of the modified zero-order Bessel's function of the first kind.

  Parameters
  ----------
  x : float
    Argument of the function.

  Returns
  -------
  s : float
    Value of the function. Named identical to fullwave3D.

  Notes
  -----
  From the original source code:
  'accuracy is <1/4%, which is quite adequate for distributed source'.
  There are discrepancies compared to Python's built-in function
  but these are for x < 0 which does not matter in Kaiser window
  (we look only at x > 0). FIXME: d-c.

  """
def bessel_fw3d(x: Any, **kwargs: Any) -> object {
    v = x * 0.5;
    a = 1.0;
    s = 1.0;
    i = 0;
    while (a > 0.03) {
        i = i + 1;
        a = a * (v / i);
        s = s + (a ** 2);
    }
    return s;
}

""" Get head indexes only for word-pieces tokenization  """
def preprocessing(list_of_tokens: Any, head_indexes_2d: Any) -> object {
    batch_size = len(list_of_tokens);
    xx = [[]] * batch_size;
    for i in range(batch_size) {
        xx[i] = [0] * len(list_of_tokens[i]);
        for (idx, item) in enumerate(head_indexes_2d[i]) {
            if (item == 0) {
                xx[i][idx] = 0;
            } else {
                xx[i][idx] = list_of_tokens[i][head_indexes_2d[i][idx]];
            }
        }
    }
    return xx;
}

